export const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>Aedrova | We’ll be right back.</title>\n<style>\n:root{color-scheme:light dark;\n--bg:#f5f6f8;\n--text:#20242c;\n--muted:#667180;\n--blue:#246bfd;\n--line:#e0e4ec}\n*{box-sizing:border-box}\nbody{margin:0;\nbackground:var(--bg);\ncolor:var(--text);\nfont-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;\n-webkit-font-smoothing:antialiased}\nheader,footer{max-width:1160px;\nmargin:auto;\npadding:30px 28px;\ndisplay:flex;\njustify-content:space-between;\nalign-items:center}\na{color:inherit;\ntext-decoration:none}\nheader a{display:flex;align-items:center;gap:9px;font-size:22px;\nfont-weight:650;\nletter-spacing:-.7px}\nheader img{width:30px;height:30px;object-fit:contain}\nheader span{color:var(--muted);\nfont-size:13px}\nmain{min-height:70vh;\nmax-width:780px;\nmargin:auto;\npadding:70px 28px 90px;\ntext-align:center}\n.scene{height:185px;\nposition:relative;\nmargin:auto auto 32px;\nmax-width:360px}\n.bud{position:absolute;\nwidth:170px;\nheight:170px;\nbackground-image:var(--atlas);\nbackground-size:300% 200%;\nbackground-position:0 0;\nleft:38px;\ntop:10px;\ntransform:rotate(-8deg)}\n.bud.small{width:110px;\nheight:110px;\nbackground-position:100% 0;\nleft:auto;\nright:20px;\ntop:65px;\ntransform:rotate(12deg)}\n.code{font-size:12px;\nletter-spacing:.15em;\ncolor:var(--muted);\nfont-weight:600}\nh1{font-size:clamp(34px,6vw,56px);\nline-height:1.07;\nletter-spacing:-.045em;\nmargin:20px 0;\nfont-weight:650}\np{max-width:510px;\nmargin:0 auto;\ncolor:var(--muted);\nfont-size:16px;\nline-height:1.65}\n.actions{display:flex;\njustify-content:center;\ngap:20px;\nalign-items:center;\nmargin:32px 0;\nflex-wrap:wrap}\n.primary{background:var(--blue);\ncolor:white;\npadding:15px 25px;\nborder-radius:12px;\nfont-size:14px;\nfont-weight:600;\ntransition:transform .15s}\n.primary:hover{transform:translateY(-2px)}\n.primary:active{transform:scale(.98)}\n.secondary{font-size:14px}\na:focus-visible{outline:3px solid var(--blue);\noutline-offset:5px}\n.note{font-size:12px}\nfooter{border-top:1px solid var(--line);\nfont-size:12px;\ncolor:var(--muted);\ngap:20px;\nflex-wrap:wrap}\nfooter nav{display:flex;\ngap:24px}\n@media(prefers-color-scheme:dark){:root{--bg:#18191c;\n--text:#f5f6f8;\n--muted:#a4acb8;\n--line:#303238;\n--blue:#397dff}\n}\n@media(max-width:500px){header,footer{padding:24px}\nmain{padding-top:35px}\nheader span{display:none}\n.scene{transform:scale(.9);\nmargin-bottom:10px}\n}\n@media(prefers-reduced-motion:reduce){.primary{transition:none}\n}\n\n\n.bud{background-image:url('data:image/png;base64,')}</style>\n</head>\n<body>\n<header>\n<a href=\"/\" aria-label=\"Aedrova home\">\n<img src=\"data:image/png;base64,\" alt=\"\" width=\"30\" height=\"30\">Aedrova</a>\n<span>Your team, plus Agents.</span>\n</header>\n<main>\n<div class=\"scene\" aria-hidden=\"true\">\n<div class=\"bud\">\n</div>\n<div class=\"bud small\">\n</div>\n</div>\n<div class=\"code\">503 · Service Unavailable</div>\n<h1>We’ll be right back.</h1>\n<p>Aedrova is temporarily unavailable. We’re working to get things back up. Please try again shortly.</p>\n<div class=\"actions\">\n<a class=\"primary\" href=\"/\">Try again</a>\n<a class=\"secondary\" href=\"mailto:contact@aedrova.com\">Contact support ↗</a>\n</div>\n<p class=\"note\">Your workspace stays private. Contact us if you need a hand.</p>\n</main>\n<footer>\n<span>Aedrova · Your team. Your tools. Together.</span>\n<nav>\n<a href=\"/privacy\">Privacy</a>\n<a href=\"/terms\">Terms</a>\n</nav>\n</footer>\n</body>\n</html>";
